#!/usr/bin/env python3
"""Rebuild the released-packages table in README.md from packages.json.

A package counts as *released* when r-universe can actually serve it:
  * entries tracking a branch/tag (or the default branch) are built
    continuously, so they count as released with the Version from their
    DESCRIPTION at that ref;
  * entries with "branch": "*release" count only once their repository
    has a published GitHub release -- the version is read from the
    DESCRIPTION at the release tag, and the release itself is linked.
    Until then the package is listed under the table as awaiting its
    first release instead of pretending to be published.

Only the README region between the BEGIN/END markers below is rewritten,
so the rest of the file can be edited freely:

    <!-- BEGIN: released-packages (...) -->
    <!-- END: released-packages -->

Usage:
    python3 .github/scripts/update_readme.py            # rewrite table
    python3 .github/scripts/update_readme.py --dry-run  # print table only
    python3 .github/scripts/update_readme.py --check    # fail if out of date
"""

from __future__ import annotations

import argparse
import os
import sys
import urllib.parse
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from registry_common import (  # noqa: E402
    DEFAULT_REGISTRY,
    DiscoveryError,
    GitHub,
    fetch_description,
    get_repo,
    latest_release,
    load_config,
    load_registry,
    log,
    make_github_client,
    parse_github_repo,
    resolve_owner,
    run_main,
    warn,
)

BEGIN_MARKER = ("<!-- BEGIN: released-packages "
                "(generated by .github/scripts/update_readme.py; do not edit) -->")
END_MARKER = "<!-- END: released-packages -->"


def md_cell(text: str) -> str:
    """Make text safe for one Markdown table cell."""
    return " ".join(str(text).split()).replace("|", "\\|")


def _describe_package(
    gh: GitHub, entry: dict, include_unreleased: bool, warnings: list[str]
) -> tuple[bool, str, str, dict | None]:
    """Return (released, version, title, release) for one registry entry."""
    package = str(entry.get("package", ""))
    url = str(entry.get("url", ""))
    subdir = str(entry.get("subdir") or "")
    branch = str(entry.get("branch") or "")
    release: dict | None = None
    released = True
    ref: str | None = None

    parsed = parse_github_repo(url) if "github.com" in url.lower() else None
    if not parsed:  # external Git host: trust the registry, can't inspect it
        if branch == "*release":
            released = False
            warn(warnings, f"{package}: *release cannot be resolved for "
                           f"non-GitHub URL {url}")
        return released, "", "", None

    repo_owner, repo = parsed
    if branch == "*release":
        try:
            release = latest_release(gh, repo_owner, repo)
        except DiscoveryError as error:
            warn(warnings, f"{package}: could not check releases ({error})")
        if release:
            ref = release["tag_name"]
        else:
            released = False
    if not released and not include_unreleased:
        return released, "", "", None

    if not ref:
        if branch and branch != "*release":
            ref = branch
        else:
            try:
                ref = get_repo(gh, repo_owner, repo).get("default_branch") or "HEAD"
            except DiscoveryError as error:
                warn(warnings, f"{package}: could not read repo metadata ({error})")
                ref = "HEAD"
    try:
        fields = fetch_description(gh, repo_owner, repo, subdir, ref)
    except DiscoveryError as error:
        warn(warnings, f"{package}: could not read DESCRIPTION at {ref} ({error})")
        return released, "", "", release
    described = fields.get("Package", "").strip()
    if described and described != package:
        warn(warnings, f"{package}: DESCRIPTION at {ref} names the package "
                       f"{described!r}; the registry entry should be fixed")
    return (
        released,
        fields.get("Version", "").strip(),
        fields.get("Title", "").strip(),
        release,
    )


def collect_rows(
    gh: GitHub, entries: list[dict], universe_url: str,
    include_unreleased: bool, warnings: list[str],
) -> tuple[list[str], list[tuple[str, str]]]:
    """Build Markdown table rows plus the (package, url) awaiting-release list."""
    universe_url = universe_url.rstrip("/")
    rows: list[str] = []
    awaiting: list[tuple[str, str]] = []
    for entry in sorted(entries, key=lambda e: str(e.get("package", "")).lower()):
        package = str(entry.get("package", "")).strip()
        url = str(entry.get("url", "")).strip()
        if not package or not url:
            warn(warnings, f"skipping malformed registry entry: {entry!r}")
            continue
        released, version, title, release = _describe_package(
            gh, entry, include_unreleased, warnings
        )
        if not released:
            awaiting.append((package, url))
            if not include_unreleased:
                continue
        quoted = urllib.parse.quote(package)
        links = [f"[Source]({url})"]
        if release:
            tag = str(release["tag_name"]).replace("`", "")
            links.append(f"[Release `{tag}`]({release['html_url']})")
        if released:
            links.append(f"[Docs]({universe_url}/{quoted}/doc/manual.html)")
        rows.append(
            f"| [`{package}`]({universe_url}/{quoted}) "
            f"| {md_cell(version) or '—'} "
            f"| {md_cell(title) or '—'} "
            f"| {' · '.join(links)} |"
        )
    return rows, awaiting


def render_section(rows: list[str], awaiting: list[tuple[str, str]]) -> str:
    """Render the whole generated region (between the markers)."""
    if rows:
        lines = ["| Package | Version | Title | Links |",
                 "| --- | --- | --- | --- |", *rows]
    else:
        lines = ["_No released packages yet._"]
    if awaiting:
        names = ", ".join(f"[`{package}`]({url})" for package, url in awaiting)
        lines += ["", f"_Awaiting first release: {names}._"]
    return "\n".join(lines)


def replace_section(readme: str, section: str) -> str:
    """Swap the generated region of README, keeping everything else verbatim."""
    if readme.count(BEGIN_MARKER) != 1 or readme.count(END_MARKER) != 1:
        raise DiscoveryError(
            "README must contain exactly one released-packages marker pair:\n"
            f"  {BEGIN_MARKER}\n  {END_MARKER}"
        )
    begin = readme.index(BEGIN_MARKER) + len(BEGIN_MARKER)
    end = readme.index(END_MARKER)
    if end < begin:
        raise DiscoveryError("END marker appears before BEGIN marker in README")
    return readme[:begin] + "\n\n" + section + "\n\n" + readme[end:]


def write_step_outputs(released: int, awaiting: int, changed: bool,
                       warnings: list[str]) -> None:
    output = os.environ.get("GITHUB_OUTPUT")
    if output:
        with open(output, "a", encoding="utf-8") as handle:
            handle.write(f"released={released}\n")
            handle.write(f"awaiting_release={awaiting}\n")
            handle.write(f"readme_changed={'true' if changed else 'false'}\n")
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        lines = ["## README released-packages table", "",
                 f"**{released} released package(s)**, {awaiting} awaiting a "
                 f"first release -- README.md {'changed' if changed else 'unchanged'}."]
        if warnings:
            lines += ["", "### Warnings"] + [f"- {text}" for text in warnings]
        with open(summary, "a", encoding="utf-8") as handle:
            handle.write("\n".join(lines) + "\n")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Rebuild the released-packages table in README.md."
    )
    parser.add_argument("--readme", type=Path, default=Path("README.md"),
                        help="README file containing the marker pair")
    parser.add_argument("--registry", type=Path, default=DEFAULT_REGISTRY,
                        help="packages.json to read")
    parser.add_argument("--config", type=Path, default=None,
                        help="path to registry-discovery.json (for the owner)")
    parser.add_argument("--owner", help="universe owner "
                        "(default: config owner, else $GITHUB_REPOSITORY_OWNER)")
    parser.add_argument("--universe-url", help="universe base URL "
                        "(default: https://<owner>.r-universe.dev)")
    parser.add_argument("--include-unreleased", action="store_true",
                        help="also list packages with no release yet as table rows")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--dry-run", action="store_true",
                      help="print the generated table, write nothing")
    mode.add_argument("--check", action="store_true",
                      help="exit 1 if the table is out of date, write nothing")
    args = parser.parse_args(argv)

    if not args.readme.exists():
        raise DiscoveryError(f"README not found: {args.readme}")
    config = load_config(args.config)
    owner = resolve_owner(args.owner, config)
    universe_url = args.universe_url or config.get("universe_url") \
        or f"https://{owner.lower()}.r-universe.dev"
    entries, _ = load_registry(args.registry)
    old_readme = args.readme.read_text(encoding="utf-8")

    warnings: list[str] = []
    gh = make_github_client()
    rows, awaiting = collect_rows(
        gh, entries, universe_url, args.include_unreleased, warnings
    )
    section = render_section(rows, [] if args.include_unreleased else awaiting)
    new_readme = replace_section(old_readme, section)
    changed = new_readme != old_readme

    if args.dry_run:
        print(section)
        log(f"dry run: {len(rows)} released row(s), {len(awaiting)} awaiting; "
            f"{args.readme} {'would change' if changed else 'already up to date'}")
    elif args.check:
        if changed:
            log(f"error: {args.readme} released-packages table is out of date; "
                "run python3 .github/scripts/update_readme.py")
            return 1
        log(f"{args.readme} released-packages table is up to date")
    elif changed:
        args.readme.write_text(new_readme, encoding="utf-8")
        log(f"updated {args.readme}: {len(rows)} released package(s), "
            f"{len(awaiting)} awaiting first release")
    else:
        log(f"{args.readme} already up to date "
            f"({len(rows)} released package(s))")

    write_step_outputs(len(rows), len(awaiting), changed, warnings)
    return 0


if __name__ == "__main__":
    run_main(main)
